#include <stdio.h>
#include <stdlib.h>
typedef struct Node {
    int data;
    struct Node* next;
} Node;
void enqueue(Node** front, Node** rear, int value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = value;
    newNode->next = NULL;
    if (*rear == NULL) {
        *front = newNode;
        *rear = newNode;
    } else {
        (*rear)->next = newNode;
        *rear = newNode;
    }
}
int dequeue(Node** front) {
    if (*front == NULL) {
        printf("Queue is empty\n");
        return -1;  // Error value
    }
    Node* temp = *front;
    int value = temp->data;
    *front = temp->next;
    free(temp);
    return value;
}
int main() {
    Node* front = NULL;
    Node* rear = NULL;
    enqueue(&front, &rear, 10);
    enqueue(&front, &rear, 20);
    printf("Dequeued: %d\n", dequeue(&front));
    printf("Dequeued: %d\n", dequeue(&front));
    return 0;
}
